import { Globals, colors, createStringInterpolator } from "@react-spring/shared";
import { createHost } from "@react-spring/animated";

export * from "@react-spring/core"

//#region src/primitives.ts
const primitives = [
	"Arc",
	"Arrow",
	"Circle",
	"Ellipse",
	"FastLayer",
	"Group",
	"Image",
	"Label",
	"Layer",
	"Line",
	"Path",
	"Rect",
	"RegularPolygon",
	"Ring",
	"Shape",
	"Sprite",
	"Star",
	"Tag",
	"Text",
	"TextPath",
	"Transformer",
	"Wedge"
];

//#endregion
//#region src/index.ts
Globals.assign({
	createStringInterpolator,
	colors
});
const host = createHost(primitives, { applyAnimatedValues(instance, props) {
	if (!instance.nodeType) return false;
	instance._applyProps(instance, props);
} });
const animated = host.animated;

//#endregion
export { animated as a, animated };